inline bool AtlasLayoutMatches(std::span<const u8> image) {
    if (image.size() < AtlasInitializerEnd) return false;
    u64 hash = 14695981039346656037ULL;
    for (u64 at=AtlasInitializerStart; at<AtlasInitializerEnd; ++at)
        hash = (hash ^ image[at]) * 1099511628211ULL;
    if (hash != AtlasInitializerHash) return false;
    for (const auto& change : AtlasLayoutChanges)
        if (change.at > image.size() || change.size > image.size()-change.at ||
            std::memcmp(image.data()+change.at,change.expected.data(),change.size)!=0) return false;
    return true;
}

inline void ApplyHalfAtlasLayout(std::span<u8> image) {
    for (const auto& change : AtlasLayoutChanges)
        std::memcpy(image.data()+change.at,change.replacement.data(),change.size);
}

